        System.out.println(unique.size()); // 2
        System.out.println(unique.contains("Ada")); // true

        Map<String, Integer> scores = new HashMap<>();
        scores.put("Ada", 8);
        scores.put("Ada", 10);
        System.out.println(scores.get("Ada")); // 10
        System.out.println(scores.getOrDefault("Iva", 0)); // 0
    }
}

